import os
import json

output_dir = "/app/output"

os.makedirs(output_dir, exist_ok=True)

# Brand Colors
# Primary: #0A0A23 (dark navy)
# Accent: #FEAC32 (gold/yellow)
# Link: #002EAD (blue)

css = """
:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --accent-hover: #e09322;
  --link: #002EAD;
  --bg-color: #FFFFFF;
  --text-main: #1E293B;
  --text-muted: #64748B;
  --border: #E2E8F0;
  --bg-muted: #F8FAFC;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, sans-serif;
  color: var(--text-main);
  background-color: var(--bg-color);
  line-height: 1.6;
}

a {
  color: var(--link);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

ul {
  list-style: none;
}

/* Header */
.global-header {
  background-color: var(--primary);
  color: #FFF;
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

.logo {
  font-weight: 700;
  font-size: 1.5rem;
  color: #FFF;
  text-decoration: none;
}
.logo:hover {
  text-decoration: none;
}

.search-bar {
  flex: 1;
  max-width: 600px;
  margin: 0 2rem;
  position: relative;
}
.search-bar input {
  width: 100%;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  border: 1px solid var(--primary);
  background-color: #21213b;
  color: #fff;
}
.search-bar input::placeholder {
  color: #a0a0b0;
}

.desktop-nav {
  display: flex;
  gap: 1.5rem;
}
.desktop-nav a {
  color: #FFF;
  font-weight: 500;
}

.hamburger {
  display: none;
  background: none;
  border: none;
  color: #FFF;
  font-size: 1.5rem;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  background-color: var(--primary);
  padding: 1rem 2rem;
  flex-direction: column;
  gap: 1rem;
}
.mobile-nav a {
  color: #FFF;
  font-weight: 500;
}
.mobile-nav.open {
  display: flex;
}

/* Banner */
.global-banner {
  background-color: #F3F4F6;
  text-align: center;
  padding: 0.75rem;
  font-weight: 500;
  border-bottom: 1px solid var(--border);
}
.global-banner a {
  color: var(--text-main);
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

/* Featured Article */
.featured-card {
  display: flex;
  flex-direction: column;
  background: var(--bg-muted);
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 3rem;
  border: 1px solid var(--border);
}
.featured-img {
  width: 100%;
  height: 300px;
  background-color: #E2E8F0;
  object-fit: cover;
}
.featured-content {
  padding: 2rem;
}
.tag-label {
  display: inline-block;
  background-color: var(--text-main);
  color: #FFF;
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  text-transform: uppercase;
}
.featured-title {
  font-size: 2rem;
  margin-bottom: 1rem;
  line-height: 1.2;
}
.featured-title a {
  color: var(--text-main);
}
.meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background-color: var(--border);
}

/* Article Grid */
.section-title {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  border-bottom: 2px solid var(--border);
  padding-bottom: 0.5rem;
}
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
}
.card {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  background: #FFF;
}
.card-img {
  width: 100%;
  height: 180px;
  background-color: #E2E8F0;
  object-fit: cover;
}
.card-content {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.card .tag-label {
  background-color: #F1F5F9;
  color: var(--text-main);
  align-self: flex-start;
  font-size: 0.75rem;
  margin-bottom: 0.75rem;
}
.card-title {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  flex: 1;
}
.card-title a {
  color: var(--text-main);
}

.load-more {
  display: block;
  width: 100%;
  max-width: 300px;
  margin: 3rem auto 0;
  padding: 1rem;
  text-align: center;
  background-color: var(--primary);
  color: #FFF;
  border: none;
  border-radius: 4px;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: opacity 0.2s;
}
.load-more:hover {
  opacity: 0.9;
}

/* Footer */
footer {
  background-color: var(--bg-muted);
  padding: 3rem 2rem;
  border-top: 1px solid var(--border);
  margin-top: 4rem;
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}
.footer-mission {
  margin-bottom: 2rem;
  max-width: 800px;
  color: var(--text-muted);
}
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2rem;
}
.footer-links a {
  color: var(--text-main);
  font-weight: 500;
}

/* Curriculum / Learn Page */
.curriculum-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-bottom: 3rem;
}
.cert-card {
  padding: 1.5rem;
  background: var(--bg-muted);
  border: 1px solid var(--border);
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 1rem;
  font-size: 1.125rem;
  font-weight: 600;
}
.cert-card svg {
  width: 24px;
  height: 24px;
  color: var(--text-muted);
}
.learn-cta {
  background: var(--bg-muted);
  padding: 2rem;
  border-radius: 8px;
  margin-bottom: 2rem;
  text-align: center;
  border: 1px solid var(--border);
}
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  background-color: var(--accent);
  color: var(--primary);
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  border: none;
}
.btn:hover {
  background-color: var(--accent-hover);
  text-decoration: none;
}

/* Donate Page */
.donate-hero {
  text-align: center;
  padding: 3rem 0;
}
.donate-hero h1 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
}
.donate-hero p {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 800px;
  margin: 0 auto 2rem;
}
.donate-form {
  max-width: 500px;
  margin: 0 auto 3rem;
  background: var(--bg-muted);
  padding: 2rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  text-align: center;
}
.amount-tabs {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}
.amount-tab {
  flex: 1;
  padding: 0.75rem;
  border: 1px solid var(--border);
  background: #FFF;
  border-radius: 4px;
  font-weight: 600;
  cursor: pointer;
  color: var(--text-main);
}
.amount-tab.active {
  background: var(--primary);
  color: #FFF;
  border-color: var(--primary);
}
.donate-dynamic-text {
  margin-bottom: 1.5rem;
  font-weight: 500;
}
.btn-donate {
  width: 100%;
  padding: 1rem;
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  margin-bottom: 4rem;
}
.info-box ul {
  list-style: disc;
  padding-left: 1.5rem;
}
.info-box li {
  margin-bottom: 0.5rem;
}

/* FAQ Accordion */
.faq-container {
  max-width: 800px;
  margin: 0 auto 4rem;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  padding: 1.5rem 0;
  background: none;
  border: none;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--text-muted);
}
.faq-item.active .faq-question::after {
  content: '-';
}
.faq-answer {
  display: none;
  padding-bottom: 1.5rem;
  color: var(--text-muted);
}
.faq-item.active .faq-answer {
  display: block;
}

/* Tag Pages */
.tag-header {
  text-align: center;
  padding: 3rem 0 2rem;
}
.tag-header h1 {
  font-size: 2.5rem;
  text-transform: uppercase;
  margin-bottom: 0.5rem;
}
.tag-header p {
  color: var(--text-muted);
}
.popular-tags {
  display: flex;
  overflow-x: auto;
  gap: 1rem;
  padding-bottom: 1rem;
  margin-bottom: 3rem;
  white-space: nowrap;
}
.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: var(--bg-muted);
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: 0.875rem;
  color: var(--text-main);
}
.popular-tag span {
  color: var(--text-muted);
}

/* Mobile Responsive */
@media (max-width: 768px) {
  .desktop-nav { display: none; }
  .hamburger { display: block; }
  .search-bar { display: none; }

  .featured-card { flex-direction: column; }
  .featured-img { height: 200px; }
  .info-grid { grid-template-columns: 1fr; }
}

@media (min-width: 769px) {
  .featured-card { flex-direction: row; }
  .featured-img { width: 50%; height: auto; min-height: 350px; }
  .featured-content { width: 50%; display: flex; flex-direction: column; justify-content: center; }
}
"""

with open(f"{output_dir}/styles.css", "w") as f:
    f.write(css)

